INSERT INTO _species_audit VALUES
  ('5e808aba-8086-5d1f-abdd-c7392d31f536', 'Adenanthera pavonina', 'Adenanthera pavonina', 'Adenanthera', 'pavonina', 'Fabaceae', 'native', 'Tanglin bears shiny red seeds long used for beads and shade planting. Archived from the native-only catalog: CDFP: cultivated in the Philippines and not naturalized; POWO does not treat the Philippines as native.', 'Feathery twice-compound leaves.', 'Gray-brown bark.', 'Creamy bottlebrush flower spikes.', 'Curled pods with scarlet seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '12.00', '20.00', '8.00', '12.00', 'fast', FALSE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: cultivated in the Philippines and not naturalized; POWO does not treat the Philippines as native.', 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('49240a8a-04f3-5b45-ac7a-abeb82d7848e', 'Afzelia rhomboidea', 'Afzelia rhomboidea', 'Afzelia', 'rhomboidea', 'Fabaceae', 'native', 'Tindalo (Afzelia rhomboidea) is a Philippine-native tree in the Fabaceae family. Tindalo is a prized native hardwood with beautiful reddish grain. Philippine flora records describe its habitat as Throughout the Philippines; low to medium elevation primary forests. 0-350(-1400)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with diamond-shaped leaflets.', 'Gray-brown scaly bark.', 'Fragrant white to pinkish flowers.', 'Thick woody pods with hard black-red seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '15.00', '25.00', '8.00', '12.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Endangered', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('20000000-0000-0000-0000-000000000005', 'Agathis dammara', 'Agathis dammara', 'Agathis', 'dammara', 'Araucariaceae', 'native', 'Almaciga (Agathis dammara) is a Philippine-native tree in the Araucariaceae family. Almaciga is a majestic conifer yielding valuable Manila copal resin. Philippine flora records describe its habitat as See notes by Farjon (2010) regarding the synonymy of Agathis dammara and Agathis philippinensis. Forest emergent and locally common. Occurs mostly in montane forests. 0-2200m. Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Broad leathery opposite leaves, unlike pine needles.', 'Gray bark shedding in flakes.', 'Wind-pollinated cones.', 'Large round cones.', 'Winged seeds are borne on the scales of mature seed cones and are released as the cone breaks apart or opens.', 'large', '30.00', '50.00', '10.00', '16.00', 'slow', FALSE, FALSE, 'No global category reported in the cited Philippine checklist', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Araucariaceae.html'),
  ('ffffffff-ffff-ffff-ffff-ffffffffffff', 'Albizia procera', 'Albizia procera', 'Albizia', 'procera', 'Fabaceae', 'native', 'Akleng Parang (Albizia procera) is a Philippine-native tree in the Fabaceae family. Akleng Parang is a fast-growing native tree used in reforestation and hillside planting. Philippine flora records describe its habitat as In Luzon from Cagayan to Batangas. Second-growth forests, thickets, parang vegetation in regions subject to a long dry season. Fl. & fr. throughout the year. 0-1545m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Feathery twice-compound leaves that fold at night.', 'Smooth pale bark becoming rougher with age.', 'Creamy-white powder-puff flower heads.', 'Flat brown pods containing several hard seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '10.00', '20.00', '6.00', '12.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('acf88856-009a-5a58-ae48-5508e67df8b9', 'Aleurites moluccana', 'Aleurites moluccanus', 'Aleurites', 'moluccanus', 'Euphorbiaceae', 'native', 'Lumbang is a spreading tree whose oily nuts once lit homes. Archived from the native-only catalog: Conflicting sources: CDFP treats Philippine occurrence as cryptogenic, while POWO includes the Philippines in the native range. Archived pending expert review.', 'Large three-lobed pale leaves.', 'Gray smooth bark.', 'Small white flower clusters.', 'Hard-shelled oily nuts.', 'Seeds develop within the documented fruit: Hard-shelled oily nuts.', 'medium', '12.00', '20.00', '8.00', '14.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', TRUE, 'Conflicting sources: CDFP treats Philippine occurrence as cryptogenic, while POWO includes the Philippines in the native range. Archived pending expert review.', 'https://www.philippineplants.org/Families/Euphorbiaceae.html'),
  ('9042b73a-fd82-5c28-afc8-b85874d87a2d', 'Alstonia macrophylla', 'Alstonia macrophylla', 'Alstonia', 'macrophylla', 'Apocynaceae', 'native', 'Batino (Alstonia macrophylla) is a Philippine-native tree in the Apocynaceae family. Batino is a quick-growing native tree with large whorled leaves. Philippine flora records describe its habitat as In open forests and thickets. Common. 0-2870m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very large leaves in whorls.', 'Gray bark with milky sap.', 'Small white fragrant flower clusters.', 'Long paired pods with silky seeds.', 'Seeds develop within the documented fruit: Long paired pods with silky seeds.', 'medium', '12.00', '25.00', '6.00', '12.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Apocynaceae.html'),
  ('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee', 'Alstonia scholaris', 'Alstonia scholaris', 'Alstonia', 'scholaris', 'Apocynaceae', 'native', 'Dita (Alstonia scholaris) is a Philippine-native tree in the Apocynaceae family. Dita is a tall straight native tree with whorled leaves and fragrant night-blooming flowers. Philippine flora records describe its habitat as Luzon to Palawan and Mindanao, in most or all islands and provinces. In primary and secondary forests. 0-1371m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Glossy leaves arranged in whorls around the twigs.', 'Grayish bark with a bitter milky sap.', 'Small intensely fragrant greenish-white flowers that open at night.', 'Long slender paired pods releasing tufted seeds.', 'Seeds develop within the documented fruit: Long slender paired pods releasing tufted seeds.', 'large', '15.00', '35.00', '8.00', '14.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Apocynaceae.html'),
  ('20000000-0000-0000-0000-000000000010', 'Anisoptera aurea', 'Anisoptera aurea', 'Anisoptera', 'aurea', 'Dipterocarpaceae', 'native', 'Palosapis (Anisoptera aurea) is a Philippine-native tree in the Dipterocarpaceae family. Palosapis is a tall native dipterocarp with golden young foliage. Philippine flora records describe its habitat as Dagang. Mixed dipterocarp forest, especially on ridges. 0-600m. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large oval leaves, golden when young.', 'Pale fissured bark.', 'Small yellowish flowers.', 'Winged fruit with long wings.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '25.00', '40.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('6a834637-4cc5-58b5-bf1a-44760a504c82', 'Antidesma bunius', 'Antidesma bunius', 'Antidesma', 'bunius', 'Phyllanthaceae', 'native', 'Bignay (Antidesma bunius) is a Philippine-native tree in the Phyllanthaceae family. Bignay produces hanging clusters of dark juicy berries for wine and juice. Philippine flora records describe its habitat as As Antidesma bunius is widely cultivated as a fruit tree, it is impossible to distinguish truly wild occurrences and to establish the natural geographic distribution of the species. In wet evergreen forest, dipterocarp forest and teak forest; on river banks, at forest edges, along roadsides; in bamboo thickets; in semi-cultivated and cultivated areas; in shady or open habitats; usually in secondary but also in primary vegetation. Thrives best in open, sunny places, and is said to be common in the early stages of…. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval glossy leaves.', 'Gray-brown bark.', 'Tiny flowers in long spikes.', 'Long strands of red-to-black berries.', 'Seeds develop within the documented fruit: Long strands of red-to-black berries.', 'small', '5.00', '12.00', '3.00', '7.00', 'moderate', TRUE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Phyllanthaceae.html'),
  ('6fc17dd8-03f1-51d0-887f-75dd26187be3', 'Artocarpus blancoi', 'Artocarpus blancoi', 'Artocarpus', 'blancoi', 'Moraceae', 'endemic', 'Antipolo (Artocarpus blancoi) is a Philippine endemic tree in the Moraceae family. Antipolo is an endemic tree named after the city, with large fruit. Philippine flora records describe its habitat as Thickets and forests at sea level and low and medium elevation. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Huge rough leaves.', 'Dark gray bark.', 'Clustered small flowers.', 'Large round greenish fruit.', 'Seeds develop within the documented fruit: Large round greenish fruit.', 'medium', '10.00', '20.00', '6.00', '12.00', 'moderate', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('8a748a9d-7a40-57c7-9a0d-dd0644a6f1b2', 'Artocarpus camansi', 'Artocarpus camansi', 'Artocarpus', 'camansi', 'Moraceae', 'native', 'Kamansi bears seeded breadfruit-like heads, a traditional famine food. Archived from the native-only catalog: CDFP: naturalized/possibly naturalized in the Philippines; native range centered in Moluccas and New Guinea.', 'Deeply lobed rough leaves.', 'Gray bark.', 'Small clustered flowers.', 'Large green heads full of edible seeds.', 'Seeds develop within the documented fruit: Large green heads full of edible seeds.', 'medium', '12.00', '20.00', '8.00', '12.00', 'moderate', TRUE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: naturalized/possibly naturalized in the Philippines; native range centered in Moluccas and New Guinea.', 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('4fc14c84-a6c3-57fc-b6b9-bc12f4755881', 'Artocarpus odoratissimus', 'Artocarpus odoratissimus', 'Artocarpus', 'odoratissimus', 'Moraceae', 'native', 'Marang bears large sweet-smelling fruit and grows well in Mindanao farms. Archived from the native-only catalog: CDFP: naturalized in the Philippines; native-range treatment does not support a strict Philippine-native catalog entry.', 'Very large lobed rough leaves.', 'Gray bark.', 'Small clustered flowers.', 'Large spiny sweet fruit.', 'Seeds develop within the documented fruit: Large spiny sweet fruit.', 'medium', '12.00', '20.00', '8.00', '12.00', 'moderate', TRUE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: naturalized in the Philippines; native-range treatment does not support a strict Philippine-native catalog entry.', 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('a37c524a-7fba-5234-841f-b4ac8f21d7dc', 'Artocarpus ovatus', 'Artocarpus ovatus', 'Artocarpus', 'ovatus', 'Moraceae', 'endemic', 'Anubing (Artocarpus ovatus) is a Philippine endemic tree in the Moraceae family. Anubing is an endemic forest tree with edible fruit favored by wildlife. Philippine flora records describe its habitat as Forests, often common. 0-760m. Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large rough oval leaves.', 'Gray-brown bark.', 'Tiny flowers packed in heads.', 'Round yellow fruit with edible pulp.', 'Seeds develop within the documented fruit: Round yellow fruit with edible pulp.', 'medium', '12.00', '20.00', '6.00', '10.00', 'moderate', TRUE, TRUE, 'No global category reported in the cited Philippine checklist', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('a1c4148a-df9d-54e8-8c07-fab8fb3e4b9a', 'Barringtonia asiatica', 'Barringtonia asiatica', 'Barringtonia', 'asiatica', 'Lecythidaceae', 'native', 'Botong (Barringtonia asiatica) is a Philippine-native tree in the Lecythidaceae family. Botong lines tropical beaches with big showy night flowers and floating fruit. Philippine flora records describe its habitat as Mostly on seashores. 0m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very large glossy leaves in rosettes.', 'Gray-brown fissured bark.', 'Large white-pink powder-puff night flowers.', 'Large square buoyant fruit dispersed by sea.', 'Seeds develop within the documented fruit: Large square buoyant fruit dispersed by sea.', 'medium', '10.00', '20.00', '8.00', '14.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Lecythidaceae.html'),
  ('2bfb7c26-6503-54e4-b945-b9a1e66d4d54', 'Barringtonia racemosa', 'Barringtonia racemosa', 'Barringtonia', 'racemosa', 'Lecythidaceae', 'native', 'Putat (Barringtonia racemosa) is a Philippine-native tree in the Lecythidaceae family. Putat favors riverbanks and back-mangroves with hanging flower spikes. Philippine flora records describe its habitat as Mostly along lakes and seashores. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large oval leaves clustered at twig ends.', 'Dark gray bark.', 'Long hanging spikes of pink-white flowers.', 'Oval ribbed fruit.', 'Seeds develop within the documented fruit: Oval ribbed fruit.', 'small', '8.00', '15.00', '5.00', '9.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Lecythidaceae.html'),
  ('aa63cd06-6a92-5ae1-8fd4-34fab335d090', 'Bischofia javanica', 'Bischofia javanica', 'Bischofia', 'javanica', 'Phyllanthaceae', 'native', 'Tuai (Bischofia javanica) is a Philippine-native tree in the Phyllanthaceae family. Tuai is a tough native tree with red young leaves, good for watersheds. Philippine flora records describe its habitat as Throughout the Philippines. Pioneer species up to 1500(-2350)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Three-part leaves flushing bright red.', 'Dark gray fissured bark.', 'Small greenish flowers.', 'Small dark berries.', 'Seeds develop within the documented fruit: Small dark berries.', 'large', '15.00', '30.00', '8.00', '14.00', 'moderate', FALSE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Phyllanthaceae.html'),
  ('12345678-1234-1234-1234-123456789012', 'Bombax ceiba', 'Bombax ceiba', 'Bombax', 'ceiba', 'Malvaceae', 'native', 'Malabulak (Bombax ceiba) is a Philippine-native tree in the Malvaceae family. Malabulak produces spectacular large red flowers on nearly leafless branches in the dry season. Philippine flora records describe its habitat as Scattered in secondary and primary forests at low and medium elevation. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with five to seven leaflets, shed before flowering.', 'Gray bark armed with stout conical spines when young.', 'Very large waxy red flowers rich in nectar.', 'Woody capsules splitting to release cottony floss and seeds.', 'Seeds develop within the documented fruit: Woody capsules splitting to release cottony floss and seeds.', 'large', '15.00', '30.00', '10.00', '18.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Bombacaceae.html'),
  ('ace3a2f6-5a72-52a2-baaa-2b5b95d8caec', 'Broussonetia luzonica', 'Allaeanthus luzonicus', 'Allaeanthus', 'luzonicus', 'Moraceae', 'native', 'Himbabao (Allaeanthus luzonicus) is a Philippine-native tree in the Moraceae family. Himbabao is an native tree whose young leaves are cooked as a vegetable. Philippine flora records describe its habitat as N Luzon to Mindanao and Basilan. Sea-level up to medium elevation thickets and secondary forests. 0m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Rough variable-shaped leaves.', 'Gray-brown bark.', 'Small separate male and female flower balls.', 'Orange-red bumpy aggregate fruit.', 'Seeds develop within the documented fruit: Orange-red bumpy aggregate fruit.', 'small', '6.00', '12.00', '4.00', '8.00', 'fast', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('88888888-8888-8888-8888-888888888888', 'Calophyllum inophyllum', 'Calophyllum inophyllum', 'Calophyllum', 'inophyllum', 'Calophyllaceae', 'native', 'Bitaog (Calophyllum inophyllum) is a Philippine-native tree in the Calophyllaceae family. Bitaog is a sturdy coastal tree with glossy leaves and fragrant white flowers. Philippine flora records describe its habitat as Throughout the Philippines along the seashore, a characteristic strand tree. 0-200m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Thick glossy oval leaves with fine parallel veins.', 'Gray to brown bark with shallow fissures.', 'Fragrant white flowers with yellow centers in clusters.', 'Round green fruit turning yellow-brown when ripe.', 'Seeds develop within the documented fruit: Round green fruit turning yellow-brown when ripe.', 'large', '12.00', '25.00', '8.00', '14.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Calophyllaceae.html'),
  ('20000000-0000-0000-0000-000000000001', 'Cananga odorata', 'Cananga odorata', 'Cananga', 'odorata', 'Annonaceae', 'native', 'Ylang-ylang is famed worldwide for its intensely fragrant flowers used in perfume. Archived from the native-only catalog: CDFP: cryptogenic; native country is unresolved and cultivated origin has been proposed.', 'Long glossy drooping leaves.', 'Gray-brown bark, fairly smooth.', 'Large drooping yellow-green highly fragrant flowers.', 'Clusters of small dark fleshy fruit, inedible.', 'Seeds develop within the documented fruit: Clusters of small dark fleshy fruit, inedible.', 'medium', '10.00', '20.00', '6.00', '12.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: cryptogenic; native country is unresolved and cultivated origin has been proposed.', 'https://www.philippineplants.org/Families/Annonaceae.html'),
  ('bb7fc5b5-f60a-5061-bd01-9063309d21cd', 'Canarium asperum', 'Canarium asperum', 'Canarium', 'asperum', 'Burseraceae', 'native', 'Pagsahingin (Canarium asperum) is a Philippine-native tree in the Burseraceae family. Pagsahingin is a resinous native tree related to Pili. Philippine flora records describe its habitat as Medium elevation forests. 0-1250(-1800)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound rough-textured leaves.', 'Gray bark with resin.', 'Small greenish flowers.', 'Small dark oval fruit.', 'Seeds develop within the documented fruit: Small dark oval fruit.', 'medium', '12.00', '22.00', '6.00', '12.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Burseraceae.html'),
  ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'Canarium ovatum', 'Canarium ovatum', 'Canarium', 'ovatum', 'Burseraceae', 'endemic', 'Pili (Canarium ovatum) is a Philippine endemic tree in the Burseraceae family. Pili is an endemic tree famous for its rich edible nuts and fragrant resin. Philippine flora records describe its habitat as Cultivated in other parts of Malesia, Melanesia and Micronesia on account of the highly prized nuts. 0-500m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with smooth oval leaflets.', 'Gray bark that exudes aromatic resin when wounded.', 'Small greenish-yellow flowers in clusters.', 'Oval purple-black fruit containing the hard-shelled pili nut.', 'Seeds develop within the documented fruit: Oval purple-black fruit containing the hard-shelled pili nut.', 'medium', '12.00', '25.00', '8.00', '14.00', 'moderate', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Burseraceae.html'),
  ('e15808d8-caed-5d5e-b641-af6206be1314', 'Cassia javanica', 'Cassia javanica', 'Cassia', 'javanica', 'Fabaceae', 'native', 'Balayong (Cassia javanica) is a Philippine-native tree in the Fabaceae family. Balayong paints streets pink and is famed as the Palawan cherry. Philippine flora records describe its habitat as Palawan Cherry. Widespread in Malesia, wild and cultivated. Now widely cultivated all over tropical Asia. In the more seasonal parts of the Philippines, low elevation. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Feathery compound leaves.', 'Gray smooth bark.', 'Showy pink-white flower clusters.', 'Long cylindrical pods.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '10.00', '18.00', '8.00', '12.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('77777777-7777-7777-7777-777777777777', 'Casuarina equisetifolia', 'Casuarina equisetifolia', 'Casuarina', 'equisetifolia', 'Casuarinaceae', 'native', 'Agoho (Casuarina equisetifolia) is a Philippine-native tree in the Casuarinaceae family. Agoho is a hardy coastal tree with needle-like branchlets, widely used for windbreaks and beach revegetation. Philippine flora records describe its habitat as Also referred to as Casuarina litorea L. Pantropic in cultivation. 0-800m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Jointed needle-like green branchlets that function like leaves.', 'Gray-brown bark, rough and fissured on older trunks.', 'Small inconspicuous male spikes and reddish female heads on the same tree.', 'Small woody cones containing winged seeds.', 'Seeds develop within the documented fruit: Small woody cones containing winged seeds.', 'large', '10.00', '25.00', '5.00', '10.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Casuarinaceae.html'),
  ('20000000-0000-0000-0000-000000000002', 'Cinnamomum mercadoi', 'Cinnamomum mercadoi', 'Cinnamomum', 'mercadoi', 'Lauraceae', 'endemic', 'Kalingag (Cinnamomum mercadoi) is a Philippine endemic tree in the Lauraceae family. Kalingag is the Philippine cinnamon, its aromatic bark harvested as spice. Philippine flora records describe its habitat as Babuyan Isls to Luzon to Mindanao; common in lowland and medium elevation forests. (?-)2000m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Glossy three-veined aromatic leaves.', 'Brown aromatic bark.', 'Small pale yellow flowers in clusters.', 'Small dark berries.', 'Seeds develop within the documented fruit: Small dark berries.', 'small', '8.00', '15.00', '4.00', '8.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Other Threatened Species', FALSE, NULL, 'https://www.philippineplants.org/Families/Lauraceae.html'),
  ('67ee09fd-a511-54e8-a5f7-00bd2bcc0928', 'Cordia dichotoma', 'Cordia dichotoma', 'Cordia', 'dichotoma', 'Cordiaceae', 'native', 'Anonang (Cordia dichotoma) is a Philippine-native tree in the Cordiaceae family. Anonang yields sticky edible fruit and fine shade. Philippine flora records describe its habitat as Throughout the Philippines in most islands and provinces. Usually common in secondary forests, thickets, etc. 0-500m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Broad oval alternate leaves.', 'Gray-brown bark.', 'Small white fragrant flowers.', 'Sticky yellowish edible drupes.', 'Seeds develop within the documented fruit: Sticky yellowish edible drupes.', 'medium', '10.00', '18.00', '6.00', '10.00', 'moderate', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Cordiaceae.html'),
  ('da39c447-b13a-52b6-bead-f3b22b271931', 'Cratoxylum sumatranum', 'Cratoxylum sumatranum', 'Cratoxylum', 'sumatranum', 'Hypericaceae', 'native', 'Salingbobog (Cratoxylum sumatranum) is a Philippine-native tree in the Hypericaceae family. Salingbobog colors open slopes with pink new leaves and yellow flowers. Philippine flora records describe its habitat as 0-800(-1200)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Small opposite leaves flushing pink.', 'Pale flaky bark.', 'Small yellow fragrant flowers.', 'Small capsules.', 'Seeds develop within the documented fruit: Small capsules.', 'small', '8.00', '15.00', '4.00', '8.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Hypericaceae.html'),
  ('cccccccc-cccc-cccc-cccc-cccccccccccc', 'Dillenia philippinensis', 'Dillenia philippinensis', 'Dillenia', 'philippinensis', 'Dilleniaceae', 'endemic', 'Katmon (Dillenia philippinensis) is a Philippine endemic tree in the Dilleniaceae family. Katmon is an endemic ornamental tree with showy white flowers and sour edible fruit. Philippine flora records describe its habitat as Widespread but absent from Palawan. 0-1000(-1800)m. The cited Philippine flora reports its conservation status as Near Threatened (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large prominently veined leaves with toothed edges.', 'Reddish-brown bark, smooth to slightly flaky.', 'Large showy white flowers with many yellow stamens.', 'Round green fruit, sour and used in local dishes.', 'Seeds develop within the documented fruit: Round green fruit, sour and used in local dishes.', 'small', '6.00', '15.00', '4.00', '8.00', 'moderate', TRUE, TRUE, 'Near Threatened (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Dilleniaceae.html'),
  ('44444444-4444-4444-4444-444444444444', 'Diospyros blancoi', 'Diospyros blancoi', 'Diospyros', 'blancoi', 'Ebenaceae', 'native', 'Kamagong (Diospyros blancoi) is a Philippine-native tree in the Ebenaceae family. Kamagong (Mabolo) is an native tree famed for its dark hardwood and sweet fruit. Philippine flora records describe its habitat as P.B. Pelser (11-Mar-23): In 1806, the name Diospyros discolor Willd. was published, but this was a superfluous name (Knapp & Gilbert 2002), because Willdenow cited "Cavanillea philippensis Lam.â (referring to Cavanillea philippensis Desr. in Lam.) and a new combination should therefore have been made with the name Diospyros philippensis. When that combination was finally made by GÃ¼rke in 1890, a different species was already named Diospyros philippinensis A.DC. (1844). Those two names (i.e. Diospyros…. Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Glossy oblong leaves, dark green above and paler beneath.', 'Dark, nearly black bark on mature trunks, rough and furrowed.', 'Small creamy bell-shaped flowers, male and female on separate trees.', 'Round velvety fruit with a sweet edible pulp when ripe.', 'Seeds develop within the documented fruit: Round velvety fruit with a sweet edible pulp when ripe.', 'medium', '10.00', '20.00', '6.00', '10.00', 'slow', TRUE, TRUE, 'No global category reported in the cited Philippine checklist', 'Co''s Digital Flora of the Philippines; DAO Vulnerable (as Diospyros discolor)', FALSE, NULL, 'https://www.philippineplants.org/Families/Ebenaceae.html'),
  ('583d2121-61ec-53d6-bac5-86a232b490f6', 'Dipterocarpus grandiflorus', 'Dipterocarpus grandiflorus', 'Dipterocarpus', 'grandiflorus', 'Dipterocarpaceae', 'native', 'Apitong (Dipterocarpus grandiflorus) is a Philippine-native tree in the Dipterocarpaceae family. Apitong is a towering dipterocarp named for its large flowers. Philippine flora records describe its habitat as Apitong. Often common and dominant in semi-evergreen lowland and medium elevation dipterocarp forests, on small islands and on coastal hills in less seasonal part. 0-700m. The cited Philippine flora reports its conservation status as Endangered (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very large oval leaves, hairy beneath when young.', 'Gray-brown bark exuding pale resin when cut.', 'Large white-pink fragrant flowers.', 'Large nut with two long wings.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '30.00', '50.00', '12.00', '20.00', 'slow', FALSE, TRUE, 'Endangered (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Dracontomelon dao', 'Dracontomelon dao', 'Dracontomelon', 'dao', 'Anacardiaceae', 'native', 'Dao (Dracontomelon dao) is a Philippine-native tree in the Anacardiaceae family. Dao is a towering native tree valued for timber and its edible sour fruit. Philippine flora records describe its habitat as In Luzon from Cagayan and Ilocos Norte to Sorsogon. Common in primary and secondary forests. In high rainfall areas, although sometimes with a short dry season. 0-500(-1840)m. Common name: Dao. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large compound leaves with many pointed leaflets.', 'Gray-brown bark, relatively smooth with shallow cracks.', 'Small greenish-yellow flowers in large branched clusters.', 'Rounded fleshy fruit, green turning yellow, edible when ripe.', 'Seeds develop within the documented fruit: Rounded fleshy fruit, green turning yellow, edible when ripe.', 'large', '20.00', '40.00', '12.00', '20.00', 'moderate', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Other Threatened Species', FALSE, NULL, 'https://www.philippineplants.org/Families/Anacardiaceae.html'),
  ('6b377db7-9d74-57e4-a8b8-692f82b5684b', 'Dracontomelon edule', 'Dracontomelon edule', 'Dracontomelon', 'edule', 'Anacardiaceae', 'endemic', 'Uas (Dracontomelon edule) is a Philippine endemic tree in the Anacardiaceae family. Uas is a rare endemic relative of Dao with edible fruit. Philippine flora records describe its habitat as Common in lowland primary forests, along riverbanks and on hills. This species is widely considered a synonym of Dracontomelon dao, but is considered distinct in the Philippines. It is mostly a smaller tree with larger fruits, and lacks the great sweeping buttresses of Dracontomelon dao. Common name: Lamio. Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with pointed leaflets.', 'Gray bark.', 'Small greenish flowers.', 'Small round edible fruit.', 'Seeds develop within the documented fruit: Small round edible fruit.', 'medium', '12.00', '20.00', '6.00', '10.00', 'moderate', TRUE, TRUE, 'No global category reported in the cited Philippine checklist', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Anacardiaceae.html'),
  ('20000000-0000-0000-0000-000000000009', 'Elaeocarpus calomala', 'Elaeocarpus calomala', 'Elaeocarpus', 'calomala', 'Elaeocarpaceae', 'endemic', 'Kalomala (Elaeocarpus calomala) is a Philippine endemic tree in the Elaeocarpaceae family. Kalomala decorates itself with fringed white flowers and blue fruit for birds. Philippine flora records describe its habitat as 200-1200m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval toothed leaves.', 'Gray smooth bark.', 'White delicately fringed flowers.', 'Blue olive-like fruit favored by birds.', 'Seeds develop within the documented fruit: Blue olive-like fruit favored by birds.', 'small', '8.00', '15.00', '4.00', '8.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Elaeocarpaceae.html'),
  ('f0931658-a038-55f3-a1de-500a0d9039b7', 'Erythrina variegata', 'Erythrina variegata', 'Erythrina', 'variegata', 'Fabaceae', 'native', 'Dapdap (Erythrina variegata) is a Philippine-native tree in the Fabaceae family. Dapdap bursts into red-orange bloom and fixes nitrogen in poor soils. Philippine flora records describe its habitat as Throughout the Philippines along the seashore, frequently planted inland. The typical form with mottled leaves occurs occasionally in the Philippines in cultivation. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Broad three-part leaves.', 'Gray bark with small prickles.', 'Dense clusters of red-orange flowers.', 'Dark pods with red seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '10.00', '18.00', '6.00', '12.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('99999999-9999-9999-9999-999999999999', 'Eucalyptus deglupta', 'Eucalyptus deglupta', 'Eucalyptus', 'deglupta', 'Myrtaceae', 'native', 'Bagras (Eucalyptus deglupta) is a Philippine-native tree in the Myrtaceae family. Bagras, or rainbow eucalyptus, is remarkable for its multicolored peeling bark and very fast growth. Philippine flora records describe its habitat as Note by P.B. Pelser (25-Oct-2020): Listed for Ilocos Norte (Luzon) by Batuyong et al. (2020), but most likely planted there. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Lance-shaped leaves that hang from slender stalks.', 'Smooth bark peeling in strips to reveal green, blue, orange, and maroon patches.', 'Small white to cream flowers in clusters.', 'Small woody capsules holding many tiny seeds.', 'Seeds develop within the documented fruit: Small woody capsules holding many tiny seeds.', 'large', '25.00', '60.00', '10.00', '18.00', 'fast', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Myrtaceae.html'),
  ('872fc8e7-eb84-5acf-84af-8880da705352', 'Ficus benjamina', 'Ficus benjamina', 'Ficus', 'benjamina', 'Moraceae', 'native', 'Balete (Ficus benjamina) is a Philippine-native tree in the Moraceae family. Balete is the familiar strangling fig of parks and old plazas. Philippine flora records describe its habitat as Forests, often in secondary growth or planted. 0-1300m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Small glossy drooping leaves.', 'Smooth gray bark, often with aerial roots.', 'Hidden fig flowers.', 'Small round figs.', 'Numerous minute seeds develop inside each fig and are dispersed mainly by fruit-eating animals.', 'large', '15.00', '30.00', '10.00', '20.00', 'moderate', FALSE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('38f95d53-30f3-501b-b9b6-ca2e38109b2d', 'Ficus nota', 'Ficus nota', 'Ficus', 'nota', 'Moraceae', 'native', 'Tibig (Ficus nota) is a Philippine-native tree in the Moraceae family. Tibig is a common native fig whose fruit feeds many birds and bats. Philippine flora records describe its habitat as Forest, often along streams. 0-1300m to 1380m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval sandpapery leaves.', 'Gray-brown bark.', 'Tiny flowers hidden inside figs.', 'Clusters of small round figs on the trunk.', 'Numerous minute seeds develop inside each fig and are dispersed mainly by fruit-eating animals.', 'small', '6.00', '12.00', '4.00', '8.00', 'fast', TRUE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('0a8a9e9b-3807-58fe-803c-5627d8bc8d1a', 'Ficus septica', 'Ficus septica', 'Ficus', 'septica', 'Moraceae', 'native', 'Hauili (Ficus septica) is a Philippine-native tree in the Moraceae family. Hauili is a fast native fig of open and riverside areas. Philippine flora records describe its habitat as Forms exist with small figs and small leaves, usually narrow, being lanceolate to linear; usually in or next to streams; more or less often rheophytic. These have been given formal taxonomic recognition as Ficus septica var. salicifolia Corner. Forests or secondary growth, often near rivers. 0-1800m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval leaves with a pointed drip tip.', 'Smooth gray bark.', 'Hidden fig flowers.', 'Small figs ripening yellow to red.', 'Numerous minute seeds develop inside each fig and are dispersed mainly by fruit-eating animals.', 'small', '5.00', '12.00', '4.00', '8.00', 'fast', TRUE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('85a82216-df72-5683-9234-e0cb31b5d627', 'Ficus ulmifolia', 'Ficus ulmifolia', 'Ficus', 'ulmifolia', 'Moraceae', 'endemic', 'Is-is (Ficus ulmifolia) is a Philippine endemic tree in the Moraceae family. Is-is is an endemic fig with sandpapery leaves once used for polishing wood. Philippine flora records describe its habitat as Widespread, but not in Palawan and Mindanao?; lowland second-growth forest, open grassy places, on rocky sites, extreme ultramafic sites. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Rough elm-like leaves.', 'Gray bark.', 'Hidden fig flowers.', 'Small hairy figs.', 'Numerous minute seeds develop inside each fig and are dispersed mainly by fruit-eating animals.', 'small', '5.00', '10.00', '3.00', '6.00', 'moderate', TRUE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Moraceae.html'),
  ('2645fce7-559c-546f-b165-1dbdacaf9b03', 'Garcinia binucao', 'Garcinia binucao', 'Garcinia', 'binucao', 'Clusiaceae', 'endemic', 'Batuan (Garcinia binucao) is a Philippine endemic tree in the Clusiaceae family. Batuan bears very sour round fruit used in Visayan cooking. Philippine flora records describe its habitat as In Luzon from Cagayan to Sorsogon, often common. 0-700m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Thick glossy opposite leaves.', 'Dark brown bark.', 'Small yellowish flowers.', 'Round yellow sour fruit.', 'Seeds develop within the documented fruit: Round yellow sour fruit.', 'small', '6.00', '12.00', '4.00', '8.00', 'slow', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Clusiaceae.html'),
  ('7b5c3803-772f-57b4-948a-364f377903a2', 'Hibiscus tiliaceus', 'Hibiscus tiliaceus', 'Hibiscus', 'tiliaceus', 'Malvaceae', 'native', 'Malubago (Hibiscus tiliaceus) is a Philippine-native tree in the Malvaceae family. Malubago is a spreading coastal tree with color-changing hibiscus flowers. Philippine flora records describe its habitat as 0-200m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Heart-shaped leaves, silvery beneath.', 'Gray-brown bark.', 'Yellow flowers turning orange-red through the day.', 'Round dry capsules.', 'Seeds develop within the documented fruit: Round dry capsules.', 'small', '6.00', '12.00', '5.00', '9.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Malvaceae.html'),
  ('20000000-0000-0000-0000-000000000006', 'Hopea plagata', 'Hopea plagata', 'Hopea', 'plagata', 'Dipterocarpaceae', 'native', 'Yakal-saplungan (Hopea plagata) is a Philippine-native tree in the Dipterocarpaceae family. Yakal-saplungan is a sturdy native dipterocarp of lowland forests. Philippine flora records describe its habitat as Yakal-saplungan. Common in semi-evergreen seasonal forests at low and medium elevation, often dominant. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval leathery leaves with clear veins.', 'Dark brown fissured bark.', 'Small cream flowers.', 'Small winged fruit.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '25.00', '40.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('20000000-0000-0000-0000-000000000008', 'Intsia acuminata', 'Intsia acuminata', 'Intsia', 'acuminata', 'Fabaceae', 'native', 'Ipil is a premier native hardwood tree of lowland forests. Archived from the native-only catalog: Taxonomic duplicate: CDFP treats Intsia acuminata as a synonym of Afzelia rhomboidea, already present as Tindalo.', 'Compound leaves with few large leaflets.', 'Gray-brown scaly bark.', 'Showy pink-white orchid-like flowers.', 'Thick woody pods with hard seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'large', '20.00', '35.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'Taxonomic duplicate: CDFP treats Intsia acuminata as a synonym of Afzelia rhomboidea, already present as Tindalo.', 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('55555555-5555-5555-5555-555555555555', 'Intsia bijuga', 'Intsia bijuga', 'Intsia', 'bijuga', 'Fabaceae', 'native', 'Ipil (Intsia bijuga) is a Philippine-native tree in the Fabaceae family. Ipil is a large native hardwood used in reforestation and coastal plantings. Philippine flora records describe its habitat as Throughout the Philippines; usually along the seashore, edge of rivers (including tidal), back of mangroves, in some localities occurring in inland forests, both primary and secondary. 0-600m. The cited Philippine flora reports its conservation status as Near Threatened (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with usually four large oval leaflets.', 'Gray-brown bark, smooth when young and rougher with age.', 'Small greenish-white flowers in loose clusters.', 'Large flat woody pods containing hard seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'large', '20.00', '40.00', '10.00', '18.00', 'moderate', FALSE, TRUE, 'Near Threatened (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('c84df45b-6fb8-5adc-95b7-057f142f8349', 'Koordersiodendron pinnatum', 'Koordersiodendron pinnatum', 'Koordersiodendron', 'pinnatum', 'Anacardiaceae', 'native', 'Amugis (Koordersiodendron pinnatum) is a Philippine-native tree in the Anacardiaceae family. Amugis is a sturdy native timber tree of lowland forests. Philippine flora records describe its habitat as Luzon (Cagayan) to Palawan and Mindanao. Forests, on dryland or occasionally inundated areas. 0-460(-1219)m. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Long compound leaves.', 'Dark fissured bark.', 'Small reddish flower clusters.', 'Small dry nutlets.', 'Seeds develop within the documented fruit: Small dry nutlets.', 'large', '20.00', '35.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Other Threatened Species', FALSE, NULL, 'https://www.philippineplants.org/Families/Anacardiaceae.html'),
  ('33333333-3333-3333-3333-333333333333', 'Lagerstroemia speciosa', 'Lagerstroemia speciosa', 'Lagerstroemia', 'speciosa', 'Lythraceae', 'native', 'Banaba (Lagerstroemia speciosa) is a Philippine-native tree in the Lythraceae family. Banaba is a showy native tree with large purple-pink flower clusters, widely planted in urban landscapes. Philippine flora records describe its habitat as Mostly in secondary forests at low and medium elevation. 0-500m to 700m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large smooth oval leaves that may turn reddish before falling.', 'Smooth pale bark that sheds in thin patches.', 'Large clusters of showy purple to pinkish flowers in the wet season.', 'Woody capsules that split to release winged seeds.', 'Seeds develop within the documented fruit: Woody capsules that split to release winged seeds.', 'medium', '10.00', '20.00', '6.00', '12.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Lythraceae.html'),
  ('ae99e068-db4d-5afd-88b2-a3d5d578aac7', 'Macaranga tanarius', 'Macaranga tanarius', 'Macaranga', 'tanarius', 'Euphorbiaceae', 'native', 'Takip-asin (Macaranga tanarius) is a Philippine-native tree in the Euphorbiaceae family. Takip-asin is a classic pioneer with round peltate leaves. Philippine flora records describe its habitat as Throughout the Philippines, characteristic of thickets and second-growth forests at sea level and low and medium elevation. 0-2100m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Round shield-like leaves on long stalks.', 'Smooth gray bark.', 'Small yellowish flower spikes.', 'Small spiny capsules.', 'Seeds develop within the documented fruit: Small spiny capsules.', 'small', '5.00', '10.00', '3.00', '6.00', 'fast', FALSE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Euphorbiaceae.html'),
  ('1aebf139-4b7d-5191-bda9-0ab43e7261fb', 'Madhuca betis', 'Madhuca betis', 'Madhuca', 'betis', 'Sapotaceae', 'native', 'Betis (Madhuca betis) is a Philippine-native tree in the Sapotaceae family. Betis is a slow native hardwood with sweet edible flowers. Philippine flora records describe its habitat as Primary Lowland rainforests. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Clustered oblong glossy leaves.', 'Dark fissured bark.', 'Creamy fragrant drooping flowers.', 'Oval fleshy fruit.', 'Seeds develop within the documented fruit: Oval fleshy fruit.', 'medium', '12.00', '20.00', '6.00', '10.00', 'slow', TRUE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Endangered', FALSE, NULL, 'https://www.philippineplants.org/Families/Sapotaceae.html'),
  ('20000000-0000-0000-0000-000000000004', 'Mangifera odorata', 'Mangifera odorata', 'Mangifera', 'odorata', 'Anacardiaceae', 'native', 'Huani bears strongly aromatic mango-like fruit loved across Mindanao. Archived from the native-only catalog: CDFP: cryptogenic and possibly of cultivated or hybrid origin.', 'Long leathery mango-like leaves.', 'Dark gray fissured bark.', 'Large sprays of small fragrant pinkish flowers.', 'Oval strongly scented edible fruit.', 'Seeds develop within the documented fruit: Oval strongly scented edible fruit.', 'medium', '15.00', '25.00', '10.00', '14.00', 'moderate', TRUE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: cryptogenic and possibly of cultivated or hybrid origin.', 'https://www.philippineplants.org/Families/Anacardiaceae.html'),
  ('a2c481fb-4436-5ce0-a0c3-ebc494d9eab8', 'Parashorea malaanonan', 'Parashorea malaanonan', 'Parashorea', 'malaanonan', 'Dipterocarpaceae', 'native', 'Bagtikan (Parashorea malaanonan) is a Philippine-native tree in the Dipterocarpaceae family. Bagtikan is a massive emergent dipterocarp of primary rainforest. Philippine flora records describe its habitat as Bagtikan. Primary lowland forests, common. 0-1300m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very large leathery oval leaves.', 'Thick gray bark with resin.', 'Small white flowers.', 'Large winged fruit.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '30.00', '50.00', '14.00', '22.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('aeb07d9d-715e-5f87-8910-f038b6cc0e25', 'Parkia timoriana', 'Parkia timoriana', 'Parkia', 'timoriana', 'Fabaceae', 'native', 'Kupang (Parkia timoriana) is a Philippine-native tree in the Fabaceae family. Kupang is a tall native legume with edible flower buds and pods. Philippine flora records describe its habitat as In Luzon from La Union and Pampanga to Laguna. Low and medium elevation forest, especially in the more seasonal parts of W Philippines. Briefly deciduous. 0-600(-1300)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very fine feathery leaves.', 'Gray-brown bark.', 'Creamy ball-shaped flower heads.', 'Long flat pods with edible seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'large', '15.00', '30.00', '10.00', '16.00', 'fast', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('ea6fbff0-7860-583b-9e2f-4364c6e93c52', 'Peltophorum pterocarpum', 'Peltophorum pterocarpum', 'Peltophorum', 'pterocarpum', 'Fabaceae', 'native', 'Siar (Peltophorum pterocarpum) is a Philippine-native tree in the Fabaceae family. Siar is a fast deciduous tree with golden bloom, common in avenues. Philippine flora records describe its habitat as Usually along coastal forests and behind mangroves. Now extensively cultivated elsewhere in parks and roadsides as an ornamental shade tree. 0m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Feathery twice-compound leaves.', 'Gray-brown bark.', 'Bright yellow flower sprays.', 'Flat coppery pods.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '12.00', '20.00', '8.00', '14.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('20000000-0000-0000-0000-000000000003', 'Pinus kesiya', 'Pinus kesiya', 'Pinus', 'kesiya', 'Pinaceae', 'native', 'Benguet Pine (Pinus kesiya) is a Philippine-native tree in the Pinaceae family. Benguet pine cloaks the Cordillera highlands and anchors watershed forests. Philippine flora records describe its habitat as (300-)700-2700m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Long slender needles in bundles of three.', 'Thick reddish-brown scaly bark.', 'Wind-pollinated cones, not true flowers.', 'Woody cones releasing winged seeds.', 'Winged seeds are borne on the scales of mature seed cones and are released as the cone breaks apart or opens.', 'large', '20.00', '35.00', '8.00', '14.00', 'moderate', FALSE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Pinaceae.html'),
  ('6289acf8-fa32-58eb-8fdd-d613d1eec08a', 'Pittosporum pentandrum', 'Pittosporum pentandrum', 'Pittosporum', 'pentandrum', 'Pittosporaceae', 'native', 'Mamalis (Pittosporum pentandrum) is a Philippine-native tree in the Pittosporaceae family. Mamalis is a fragrant-flowered native tree of forest edges. Philippine flora records describe its habitat as Parang vegetation, occasionally in rainforest. (?-)2300m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Narrow glossy leaves in whorls.', 'Dark gray bark.', 'Sweet-scented white bell flowers.', 'Small orange capsules.', 'Seeds develop within the documented fruit: Small orange capsules.', 'small', '5.00', '10.00', '3.00', '6.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Pittosporaceae.html'),
  ('27879c2c-6b93-5929-9565-974041a81573', 'Polyscias nodosa', 'Polyscias nodosa', 'Polyscias', 'nodosa', 'Araliaceae', 'native', 'Malapapaya (Polyscias nodosa) is a Philippine-native tree in the Araliaceae family. Malapapaya is a quick pioneer tree with large ferny foliage. Philippine flora records describe its habitat as Disturbed lowland forests and associated thickets generally. 0-1000m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Very large divided leaves.', 'Pale smooth bark.', 'Small greenish flower clusters.', 'Small dark berries.', 'Seeds develop within the documented fruit: Small dark berries.', 'small', '6.00', '12.00', '3.00', '6.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Araliaceae.html'),
  ('bdd66a95-52e5-5b31-9349-a9c48d309c57', 'Pongamia pinnata', 'Pongamia pinnata', 'Pongamia', 'pinnata', 'Fabaceae', 'native', 'Bani (Pongamia pinnata) is a Philippine-native tree in the Fabaceae family. Bani is a coastal legume tree whose seeds yield oil. Philippine flora records describe its habitat as Throughout the Philippines along the seashore, common. Also extending inland. 0m to 300m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Glossy compound leaves.', 'Gray-brown cracked bark.', 'Fragrant white-pink pea flowers.', 'Flat woody pods with oily seeds.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '10.00', '18.00', '6.00', '10.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('949939f0-0e09-5ef1-a413-fb320e525a32', 'Premna odorata', 'Premna odorata', 'Premna', 'odorata', 'Lamiaceae', 'native', 'Alagaw (Premna odorata) is a Philippine-native tree in the Lamiaceae family. Alagaw is a fragrant native shrub-tree used in traditional teas. Philippine flora records describe its habitat as Throughout the archipelago in most islands and provinces. Common in lowland thickets and secondary forests. 25-1800m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval aromatic leaves.', 'Pale flaky bark.', 'Small fragrant white flower clusters.', 'Small dark berries.', 'Seeds develop within the documented fruit: Small dark berries.', 'small', '4.00', '8.00', '3.00', '5.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Lamiaceae.html'),
  ('11111111-1111-1111-1111-111111111111', 'Pterocarpus indicus', 'Pterocarpus indicus', 'Pterocarpus', 'indicus', 'Fabaceae', 'native', 'Narra (Pterocarpus indicus) is a Philippine-native tree in the Fabaceae family. Narra is the national tree of the Philippines, valued for its hardwood and favored as a shade and landscape tree where space allows. Philippine flora records describe its habitat as 0-1300m. The cited Philippine flora reports its conservation status as Endangered (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with oval leaflets arranged alternately along the stalk.', 'Grayish-brown bark that may become fissured with age.', 'Small fragrant yellow flowers borne in branched clusters during the dry season.', 'Flat rounded pods with a broad papery wing surrounding the seed.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'large', '15.00', '30.00', '8.00', '15.00', 'moderate', FALSE, TRUE, 'Endangered (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('02197e71-56ae-573d-8b2f-2c37a30d37d0', 'Sandoricum vidalii', 'Sandoricum koetjape', 'Sandoricum', 'koetjape', 'Meliaceae', 'native', 'Malasantol (Sandoricum koetjape) is a Philippine-native tree in the Meliaceae family. Malasantol is an native wild relative of santol with tart fruit. Philippine flora records describe its habitat as Native and naturalized in the primary and secondary forests of Malesia from sea level to 1200m, or more. The wild form extends from Sumatra eastwards across Malesia to New Guinea. The cultivated forms in the Philippines falls mainly in the âkechapi’ category described by Mabberley (1995). Cultivars of this include the ânative’ santol, corresponding to the Red Sentol of Corner (1940), âManila’, a robust form now cultivated outside Malesia, and âBangkok’, introduced here from Thailand in 1949. Planted and…. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large three-part leaves.', 'Gray-brown bark.', 'Small yellow-green flowers.', 'Round yellowish sour fruit.', 'Seeds develop within the documented fruit: Round yellowish sour fruit.', 'medium', '10.00', '18.00', '6.00', '10.00', 'moderate', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Meliaceae.html'),
  ('75beee58-f41a-5ee1-ba5c-3574d8005bbf', 'Shorea almon', 'Rubroshorea almon', 'Rubroshorea', 'almon', 'Dipterocarpaceae', 'native', 'Almon (Rubroshorea almon) is a Philippine-native tree in the Dipterocarpaceae family. Almon is a light-demanding native dipterocarp of disturbed lowlands. Philippine flora records describe its habitat as Almon. Primary forest on undulating hills at low elevation, on clay soil. According to Ashton (1982), particularly variable in Mindanao where the leaves are much smaller and the tomentum more sparse and scabrid in some trees. 0-1060m to 1250m (photos). The cited Philippine flora reports its conservation status as Near Threatened (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval pointed leaves on slender twigs.', 'Gray-brown flaky bark.', 'Small yellowish flowers.', 'Winged fruit.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '30.00', '50.00', '12.00', '20.00', 'moderate', FALSE, TRUE, 'Near Threatened (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('26c7c1fb-65f4-5ac5-bb84-71675a9e3c1b', 'Shorea astylosa', 'Shorea astylosa', 'Shorea', 'astylosa', 'Dipterocarpaceae', 'endemic', 'Yakal (Shorea astylosa) is a Philippine endemic tree in the Dipterocarpaceae family. Yakal is a dense endemic hardwood of lowland rainforests. Philippine flora records describe its habitat as Local in primary lowland evergreen dipterocarp forests. 200m (photos). The cited Philippine flora reports its conservation status as Endangered (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oval leathery leaves with pointed tips.', 'Dark brown bark, deeply fissured on old trunks.', 'Small yellowish flowers in branched clusters.', 'Small winged fruit typical of dipterocarps.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '20.00', '30.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Endangered (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Endangered', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('516fb15c-1092-5535-839f-4651e475ff25', 'Shorea contorta', 'Pentacme contorta', 'Pentacme', 'contorta', 'Dipterocarpaceae', 'endemic', 'White Lauan (Pentacme contorta) is a Philippine endemic tree in the Dipterocarpaceae family. White Lauan is a fast endemic dipterocarp with pale timber. Philippine flora records describe its habitat as White lauan. Common in primary lowland forests from semi-seasonal to everwet areas, in the former often semi-gregarious. In most provinces in Luzon. 0-985m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Twisted-asymmetric leaf bases, hence the name.', 'Pale gray bark, smooth to lightly fissured.', 'Small yellow-white flowers.', 'Small winged fruit.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '30.00', '50.00', '12.00', '20.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('3f3a98a1-6846-5517-93ac-dc784e76d813', 'Shorea guiso', 'Shorea guiso', 'Shorea', 'guiso', 'Dipterocarpaceae', 'native', 'Guijo (Shorea guiso) is a Philippine-native tree in the Dipterocarpaceae family. Guijo is a straight-boled native dipterocarp of lowland forests. Philippine flora records describe its habitat as Guijo. Primary lowland forests on red soils, most common in slightly seasonal areas. In most provinces in Luzon. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Oblong leaves with a rounded base.', 'Brown bark peeling in small flakes.', 'Small creamy flowers in panicles.', 'Small winged nut.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '25.00', '40.00', '10.00', '16.00', 'slow', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('660de18d-dcb8-5c82-b652-479e435ae130', 'Shorea negrosensis', 'Rubroshorea negrosensis', 'Rubroshorea', 'negrosensis', 'Dipterocarpaceae', 'endemic', 'Red Lauan (Rubroshorea negrosensis) is a Philippine endemic tree in the Dipterocarpaceae family. Red Lauan is a tall endemic dipterocarp with reddish timber. Philippine flora records describe its habitat as Primary evergreen and semi-evergreen lowland forests, common and often gregarious. Sea level and low elevation. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Elliptical leaves with prominent veins.', 'Reddish-brown bark, vertically fissured.', 'Small pale flowers in large clusters.', 'Winged nut with three long wings.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '25.00', '45.00', '10.00', '18.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('ac3da653-a045-571b-9b3e-76983ccff95b', 'Shorea palosapis', 'Rubroshorea palosapis', 'Rubroshorea', 'palosapis', 'Dipterocarpaceae', 'endemic', 'Mayapis (Rubroshorea palosapis) is a Philippine endemic tree in the Dipterocarpaceae family. Mayapis is an endemic lowland dipterocarp with light timber. Philippine flora records describe its habitat as Mayapis. Primary lowland evergreen forests on fertile well-drained soil. In some regions dominant. 0-1000m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Broad oval leaves, pale beneath.', 'Light gray bark, fairly smooth.', 'Small white fragrant flowers.', 'Winged nut.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '25.00', '40.00', '10.00', '18.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('aa531a38-4170-5d1c-9d76-7e395ed9d5e2', 'Shorea polysperma', 'Rubroshorea polysperma', 'Rubroshorea', 'polysperma', 'Dipterocarpaceae', 'native', 'Tanguile (Rubroshorea polysperma) is a Philippine-native tree in the Dipterocarpaceae family. Tanguile is one of the tallest native dipterocarps. Philippine flora records describe its habitat as Tanguile. Often common in lowland and medium elevation primary forests. 0-1100(-1200)m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large thin papery leaves.', 'Pale bark with horizontal markings.', 'Small cream flowers.', 'Many-seeded winged fruit.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '30.00', '50.00', '12.00', '20.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('00916ba8-1ff7-56f8-9dd9-8ba73e129fb2', 'Sindora supa', 'Sindora supa', 'Sindora', 'supa', 'Fabaceae', 'endemic', 'Supa (Sindora supa) is a Philippine endemic tree in the Fabaceae family. Supa is a rare endemic hardwood with fragrant oily wood. Philippine flora records describe its habitat as Forests at low and medium elevation. 5m (photos). The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with few large leaflets.', 'Dark rough bark.', 'Yellowish pea-like flowers.', 'Flat woody pods.', 'Seeds are borne inside the pod; seed size, color, and hardness vary and should be checked with the cited flora for identification.', 'medium', '12.00', '20.00', '6.00', '10.00', 'slow', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Endangered', FALSE, NULL, 'https://www.philippineplants.org/Families/Fabaceae.html'),
  ('05e23588-5a24-54da-927e-26aa1f249cb4', 'Spondias pinnata', 'Spondias pinnata', 'Spondias', 'pinnata', 'Anacardiaceae', 'native', 'Libas gives sour leaves and fruit prized in Filipino cooking. Archived from the native-only catalog: CDFP: cryptogenic in the Philippines; retained evidence is insufficient for a strict native-only catalog.', 'Compound leaves with toothed leaflets.', 'Gray-brown bark.', 'Small white-green flowers.', 'Oval yellow-green sour fruit.', 'Seeds develop within the documented fruit: Oval yellow-green sour fruit.', 'medium', '10.00', '18.00', '6.00', '10.00', 'fast', TRUE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP: cryptogenic in the Philippines; retained evidence is insufficient for a strict native-only catalog.', 'https://www.philippineplants.org/Families/Anacardiaceae.html'),
  ('dddddddd-dddd-dddd-dddd-dddddddddddd', 'Syzygium cumini', 'Syzygium cumini', 'Syzygium', 'cumini', 'Myrtaceae', 'native', 'Duhat, or Java plum, is a well-loved native fruit tree that also feeds wildlife. Archived from the native-only catalog: CDFP and POWO: naturalized/introduced in the Philippines.', 'Smooth glossy oval leaves, pinkish when young.', 'Gray-brown bark, rough and flaking in patches.', 'Small fragrant whitish flowers in clusters.', 'Oval purple-black juicy fruit, sweet-tart when ripe.', 'Seeds develop within the documented fruit: Oval purple-black juicy fruit, sweet-tart when ripe.', 'large', '10.00', '25.00', '8.00', '15.00', 'moderate', TRUE, TRUE, 'Taxonomic/native-status review required', 'Co''s Digital Flora of the Philippines', TRUE, 'CDFP and POWO: naturalized/introduced in the Philippines.', 'https://www.philippineplants.org/Families/Myrtaceae.html'),
  ('66666666-6666-6666-6666-666666666666', 'Terminalia catappa', 'Terminalia catappa', 'Terminalia', 'catappa', 'Combretaceae', 'native', 'Talisay (Terminalia catappa) is a Philippine-native tree in the Combretaceae family. Talisay is a familiar coastal and urban shade tree with pagoda-like branching. Philippine flora records describe its habitat as Commonly planted in the tropics. Throughout the Philippines along the seashore, also often planted inland. 0-5m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Large leaves clustered at branch tips, turning red before falling.', 'Gray-brown bark with shallow fissures.', 'Small greenish-white flowers on slender spikes.', 'Almond-like fruit with a fibrous husk, buoyant in seawater.', 'Seeds develop within the documented fruit: Almond-like fruit with a fibrous husk, buoyant in seawater.', 'large', '15.00', '30.00', '10.00', '20.00', 'fast', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Combretaceae.html'),
  ('60d8e024-1534-569c-947e-d362a4bb0c48', 'Thespesia populnea', 'Thespesia populnea', 'Thespesia', 'populnea', 'Malvaceae', 'native', 'Banalo (Thespesia populnea) is a Philippine-native tree in the Malvaceae family. Banalo is a classic beach tree with hibiscus-like yellow flowers. Philippine flora records describe its habitat as Widespread throughout the Philippines along seashores. Occasionally found a few km inland, whether intentionally planted or not. 0-5m (photos). The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Heart-shaped glossy leaves.', 'Gray-brown fissured bark.', 'Yellow hibiscus flowers aging to maroon.', 'Round flattened capsules.', 'Seeds develop within the documented fruit: Round flattened capsules.', 'medium', '8.00', '15.00', '6.00', '10.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Malvaceae.html'),
  ('1ea97872-b798-581f-9557-525ddf93660f', 'Toona calantas', 'Toona calantas', 'Toona', 'calantas', 'Meliaceae', 'native', 'Kalantas (Toona calantas) is a Philippine-native tree in the Meliaceae family. Kalantas is a tall native tree valued for its light reddish timber. Philippine flora records describe its habitat as In Luzon from Cagayan to Sorsogon. Primary forests at low and medium elevation. Note by L.L.Co: Correct status of this species has yet to be determined against the widely-distributed Toona ciliata M.Roem. and Toona sureni (Blume) Merr. The distribution of Toona ciliata largely overlaps with that of Toona sureni. Toona calantas may be a good morphologically distinct species, or simply a large-fruited geographical variant. The cited Philippine flora reports its conservation status as Data Deficient (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Long compound leaves with many toothed leaflets.', 'Gray-brown bark with long fissures.', 'Small white fragrant flowers in large sprays.', 'Small capsules releasing winged seeds.', 'Seeds develop within the documented fruit: Small capsules releasing winged seeds.', 'large', '20.00', '35.00', '10.00', '16.00', 'moderate', FALSE, TRUE, 'Data Deficient (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Meliaceae.html'),
  ('b734fc23-ddb9-5158-8ad5-f9bccf37f16d', 'Trema orientalis', 'Trema orientale', 'Trema', 'orientale', 'Cannabaceae', 'native', 'Anabiong (Trema orientale) is a Philippine-native tree in the Cannabaceae family. Anabiong is a fast pioneer tree whose small fruit feeds many birds. Philippine flora records describe its habitat as 476m (photos) to 600-2000m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Rough sandpapery oval leaves.', 'Gray-brown bark.', 'Small greenish flower clusters.', 'Tiny dark berries in clusters.', 'Seeds develop within the documented fruit: Tiny dark berries in clusters.', 'small', '5.00', '12.00', '3.00', '7.00', 'fast', TRUE, FALSE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Cannabaceae.html'),
  ('20000000-0000-0000-0000-000000000007', 'Vatica mangachapoi', 'Vatica mangachapoi', 'Vatica', 'mangachapoi', 'Dipterocarpaceae', 'native', 'Narig (Vatica mangachapoi) is a Philippine-native tree in the Dipterocarpaceae family. Narig is a valued native dipterocarp of lowland and foothill forests. Philippine flora records describe its habitat as In most provinces in Luzon. 0-800m. The cited Philippine flora reports its conservation status as Vulnerable (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Elliptical glossy leaves.', 'Brown bark with resin.', 'Small white fragrant flowers.', 'Small nut with short wings.', 'The seed is a nut dispersed with the persistent, wing-like calyx lobes; wing length and venation help separate related dipterocarps.', 'large', '20.00', '35.00', '8.00', '14.00', 'slow', FALSE, TRUE, 'Vulnerable (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Dipterocarpaceae.html'),
  ('22222222-2222-2222-2222-222222222222', 'Vitex parviflora', 'Vitex parviflora', 'Vitex', 'parviflora', 'Lamiaceae', 'native', 'Molave (Vitex parviflora) is a Philippine-native tree in the Lamiaceae family. Molave is a hardy native tree prized for its durable wood and tolerance of dry, rocky sites. Philippine flora records describe its habitat as Throughout the Philippines in most islands and provinces. Common in both secondary and primary forests, on clay loam or volcanic soils, over limestone or ultamafics at low elevation. 30-400(-800)m (photos). Fl. Apr-Dec; fr. all year round. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Compound leaves with three to five toothed leaflets.', 'Gray to brown bark, becoming rough and flaky.', 'Small bluish-purple flowers in terminal clusters.', 'Small rounded fleshy fruit that turns dark when ripe.', 'Seeds develop within the documented fruit: Small rounded fleshy fruit that turns dark when ripe.', 'medium', '8.00', '15.00', '5.00', '10.00', 'slow', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines; DAO Vulnerable', FALSE, NULL, 'https://www.philippineplants.org/Families/Lamiaceae.html'),
  ('a2f59121-838f-5f02-ba84-315ab1d1043a', 'Wrightia pubescens', 'Wrightia pubescens', 'Wrightia', 'pubescens', 'Apocynaceae', 'native', 'Lanete (Wrightia pubescens) is a Philippine-native tree in the Apocynaceae family. Lanete is a graceful native tree with fine wood used for carving. Philippine flora records describe its habitat as Low elevation thickets and forests. 0-600m. The cited Philippine flora reports its conservation status as Least Concern (IUCN 3.1). Use the identification characters and cited references together; local names alone are not sufficient for a field identification.', 'Small opposite oval leaves, softly hairy.', 'Pale gray smooth bark.', 'Fragrant white star-shaped flowers.', 'Long paired slender pods.', 'Seeds develop within the documented fruit: Long paired slender pods.', 'small', '8.00', '15.00', '4.00', '8.00', 'moderate', FALSE, TRUE, 'Least Concern (IUCN 3.1)', 'Co''s Digital Flora of the Philippines', FALSE, NULL, 'https://www.philippineplants.org/Families/Apocynaceae.html');
