-- 015_species_profile_audit.sql
-- LOCAL-ONLY audit of the 76-record Katutubong Puno starter catalog.
-- Transaction policy: backend/src/db/migrate.ts wraps each migration in BEGIN/COMMIT.
-- For manual validation/application use: psql --single-transaction --set ON_ERROR_STOP=1 -f 015_species_profile_audit.sql
-- Sources: Kew POWO/WCVP, Co's Digital Flora of the Philippines, IUCN data as reported by those sources, and DENR DAO 2017-11.
-- No new species are inserted. Confirmed introduced/naturalized and unresolved cryptogenic/duplicate records are soft-archived.

SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '5min';

CREATE TEMP TABLE _species_audit (id uuid PRIMARY KEY, old_name text, scientific_name text, genus text, epithet text, family text, native_status text, description text, leaf text, bark text, flower text, fruit text, seed text, growth_form text, min_h numeric, max_h numeric, min_c numeric, max_c numeric, growth_rate text, fruit_bearing boolean, flowering boolean, cons_status text, cons_source text, archive boolean, rationale text, cdfp_url text) ON COMMIT DROP;

DO $$ BEGIN IF (SELECT count(*) FROM _species_audit) <> 76 THEN RAISE EXCEPTION 'Audit payload must contain exactly 76 species'; END IF; IF EXISTS (SELECT 1 FROM _species_audit a LEFT JOIN species s ON s.id=a.id WHERE s.id IS NULL) THEN RAISE EXCEPTION 'One or more expected master-list UUIDs are missing'; END IF; END $$;

UPDATE species s SET scientific_name=a.scientific_name, genus=a.genus, species_epithet=a.epithet, family=a.family, native_status=a.native_status, description=a.description, leaf_description=a.leaf, bark_description=a.bark, flower_description=a.flower, fruit_description=a.fruit, seed_description=a.seed, growth_form=a.growth_form, min_height_m=a.min_h, max_height_m=a.max_h, min_canopy_m=a.min_c, max_canopy_m=a.max_c, growth_rate=a.growth_rate, fruit_bearing=a.fruit_bearing, flowering=a.flowering, conservation_status=a.cons_status, conservation_source=a.cons_source, verification_status=CASE WHEN a.archive THEN 'archived' ELSE 'verified' END, deleted_at=CASE WHEN a.archive THEN COALESCE(s.deleted_at, now()) ELSE NULL END FROM _species_audit a WHERE s.id=a.id;

DELETE FROM species_names WHERE species_id IN (SELECT id FROM _species_audit);

DELETE FROM species_references WHERE species_id IN (SELECT id FROM _species_audit) AND (title ILIKE '%sample record%' OR notes ILIKE '%Sample seed record%' OR notes LIKE 'KP-AUDIT-015:%');
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, author=EXCLUDED.author, organization=EXCLUDED.organization, publication_year=EXCLUDED.publication_year, source_type=EXCLUDED.source_type, source_url=EXCLUDED.source_url, notes=EXCLUDED.notes, accessed_at=EXCLUDED.accessed_at;

DELETE FROM species_distribution WHERE species_id IN (SELECT id FROM _species_audit);
DELETE FROM species_purposes WHERE species_id IN (SELECT id FROM _species_audit);
DELETE FROM species_planting_conditions WHERE species_id IN (SELECT id FROM _species_audit);




DO $$ BEGIN IF EXISTS (SELECT 1 FROM species s JOIN _species_audit a ON a.id=s.id WHERE s.description ILIKE '%SAMPLE RECORD%') THEN RAISE EXCEPTION 'Placeholder text remains in audited species'; END IF; IF (SELECT count(*) FROM species s JOIN _species_audit a ON a.id=s.id WHERE s.verification_status='archived' AND s.deleted_at IS NOT NULL) <> 9 THEN RAISE EXCEPTION 'Expected 9 soft-archived records'; END IF; END $$;
